import type { PrioritizedReadinessAction } from '../components/compliance/ComplianceReadinessActionQueue';
import type { ModuleGapBundle } from '../components/compliance/ComplianceReadinessGapPanel';
import { DOCUMENT_UPLOAD_PATH } from '../constants/documentRoutes';
import {
  estimatedScoreImpactForRemediation,
  remediationActionLabelForBlockedReason,
  remediationLinkForBlockedReason,
  remediationWarningTypeForBlockedReason,
} from '../constants/reportingUxLabels';

export type MsmeReadinessStep = {
  id: string;
  stepNumber: number;
  title: string;
  detail?: string | null;
  hubLink: string;
  ctaLabel: string;
  expectedScoreImpact?: number | null;
  framework?: string;
  warningType?: string;
  completed?: boolean;
};

