const simplifyMsmeStepTitle = (raw: string, hubLink?: string | null): { title: string; ctaLabel: string } => {
  const text = raw.trim();
  const matched = MSME_STEP_TITLE_OVERRIDES.find((entry) => entry.pattern.test(text));
  if (matched) {
    return { title: matched.title, ctaLabel: matched.ctaLabel };
  }
  if (hubLink === DOCUMENT_UPLOAD_PATH) {
    return { title: 'Upload supporting bills and invoices', ctaLabel: 'Upload bills' };
  }
  if (hubLink?.includes('start-assessment')) {
    return { title: 'Run your carbon assessment', ctaLabel: 'Start assessment' };
  }
  return {
    title: text.length > 90 ? `${text.slice(0, 87)}…` : text,
    ctaLabel: remediationActionLabelForBlockedReason(text),
  };
};

const stepDedupeKey = (step: { title: string; hubLink: string }) => {
  const normalizedLink = step.hubLink.split('?')[0];
  if (normalizedLink === DOCUMENT_UPLOAD_PATH || normalizedLink.includes('start-assessment')) {
    return normalizedLink;
  }
  // DEEP-BUG-032: identical titles must not all appear in the 3-step checklist.
  return step.title.toLowerCase().slice(0, 64);
};

