export const buildMsmeReadinessSteps = ({
  prioritizedActions = [],
  moduleGapDetails = {},
  moduleKeys = [],
  overallReadinessScore = null,
  maxSteps = 3,
  includeDefaultRecheck = true,
}: {
  prioritizedActions?: PrioritizedReadinessAction[];
  moduleGapDetails?: Record<string, ModuleGapBundle>;
  moduleKeys?: string[];
  overallReadinessScore?: number | null;
  maxSteps?: number;
  includeDefaultRecheck?: boolean;
}): MsmeReadinessStep[] => {
  const seen = new Set<string>();
  const candidates: Omit<MsmeReadinessStep, 'stepNumber'>[] = [];

  const pushCandidate = (step: Omit<MsmeReadinessStep, 'stepNumber'>) => {
    const key = stepDedupeKey(step);
    if (seen.has(key) || step.completed) {
      return;
    }
    seen.add(key);
    candidates.push(step);
  };

  prioritizedActions.forEach((action) => {
    const hubLink = action.hubLink || remediationLinkForBlockedReason(action.action) || '/compliance';
    const simplified = simplifyMsmeStepTitle(action.action, hubLink);
    pushCandidate({
      id: action.id,
      title: simplified.title,
      detail: action.detail,
      hubLink,
      ctaLabel: simplified.ctaLabel,
      expectedScoreImpact: action.expectedScoreImpact
        ?? estimatedScoreImpactForRemediation(action.action),
      framework: action.framework,
      warningType: remediationWarningTypeForBlockedReason(action.action),
    });
  });

  moduleKeys.forEach((moduleKey) => {
    const bundle = moduleGapDetails[moduleKey];
    if (!bundle?.gaps?.length) {
      return;
    }
    bundle.gaps.forEach((gap) => {
      const hubLink = gap.hubLink || bundle.hubLink || remediationLinkForBlockedReason(gap.label) || '/compliance';
      const simplified = simplifyMsmeStepTitle(gap.label, hubLink);
      pushCandidate({
        id: `${moduleKey}:${gap.id}`,
        title: simplified.title,
        detail: gap.detail,
        hubLink,
        ctaLabel: gap.dataFeedSatisfied ? 'Review data' : simplified.ctaLabel,
        expectedScoreImpact: estimatedScoreImpactForRemediation(gap.label),
        framework: moduleKey,
        warningType: remediationWarningTypeForBlockedReason(gap.label),
        completed: gap.dataFeedSatisfied,
      });
    });
  });

  if (candidates.length < maxSteps && (overallReadinessScore == null || overallReadinessScore < 75)) {
    DEFAULT_LOW_SCORE_STEPS.forEach((step) => {
      if (candidates.length >= maxSteps) {
        return;
      }
      if (!includeDefaultRecheck && step.id === 'default-recheck') {
        return;
      }
      if (seen.has(stepDedupeKey(step))) {
        return;
      }
      pushCandidate(step);
    });
  }

  return candidates.slice(0, maxSteps).map((step, index) => ({
    ...step,
    stepNumber: index + 1,
  }));
};

/** Actions already surfaced in the 3-step checklist — omit from duplicate hub queues. */
export const filterPrioritizedActionsOutsideSteps = (
  actions: PrioritizedReadinessAction[],
  steps: MsmeReadinessStep[]
): PrioritizedReadinessAction[] => {
  if (steps.length === 0) {
    return actions;
  }
  const stepIds = new Set(steps.map((step) => step.id));
  const stepLinkKeys = new Set(steps.map((step) => stepDedupeKey(step)));
  return actions.filter((action) => {
    if (stepIds.has(action.id)) {
      return false;
    }
    const hubLink = action.hubLink || remediationLinkForBlockedReason(action.action) || '/compliance';
    const simplified = simplifyMsmeStepTitle(action.action, hubLink);
    return !stepLinkKeys.has(stepDedupeKey({ title: simplified.title, hubLink }));
  });
};
